1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
5	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Derives the owner-identity values matching keys off: the owner's {@code memberId} and the single
10	 * {@code identityKey} that all duplicate detection is expressed through. The identity key is the SHA-256 of the
11	 * owner's normalized telephone, email and last-name Soundex (see {@link SoundexResolver}). Keeping this
12	 * here (rather than in {@link OwnerMapper} or the REST controller) mirrors {@link HouseholdResolver},
13	 * {@link LocalityResolver} and {@link MembershipLevelResolver} and gives owner-identity derivation a single home.
14	 * Unlike the static utilities it collaborates with the field normalizers, so it is a Spring component.
15	 */
16	@Component
17	public class IdentityKeyResolver {
18	
19	    private final TelephoneNormalizer telephoneNormalizer;
20	
21	    private final EmailNormalizer emailNormalizer;
22	
23	    public IdentityKeyResolver(TelephoneNormalizer telephoneNormalizer,
24	                               EmailNormalizer emailNormalizer) {
25	        this.telephoneNormalizer = telephoneNormalizer;
26	        this.emailNormalizer = emailNormalizer;
27	    }
28	
29	    /**
30	     * Derives the owner's {@code identityKey}, the single value all duplicate detection is expressed through. It is the
31	     * full lower-case SHA-256 hex digest (64 characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>},
32	     * joining the canonical E.164 telephone (see {@link TelephoneNormalizer#canonicalize}), the normalized email (see
33	     * {@link EmailNormalizer#normalize}, empty when the owner has none) and the American Soundex of the owner's last
34	     * name (see {@link SoundexResolver#soundex}). Because the telephone is part of the key, two owners that differ only
35	     * in telephone — such as two members of the same household — have different keys; only owners whose whole key
36	     * matches are duplicates.
37	     *
38	     * @param owner the owner whose identity key should be derived
39	     * @return the owner's identity key
40	     */
41	    public String deriveIdentityKey(Owner owner) {
42	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
43	        String email = emailNormalizer.normalize(owner.getEmail());
44	        String lowerEmail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
45	        String lastNameSoundex = SoundexResolver.soundex(owner.getLastName());
46	        return HexDigest.lowerHex(telephone + "|" + lowerEmail + "|" + lastNameSoundex);
47	    }
48	
49	    /**
50	     * Derives an owner's {@code memberId}, the single unified identifier formatted
51	     * {@code <REGION><FY><HASH8><CHK>}. {@code REGION} is the region code derived from the owner's postcode (see
52	     * {@link Region#forPostcode}), falling back to {@link LocalityResolver#UNKNOWN} when the postcode maps to no known
53	     * region; {@code FY} is the two-digit fiscal-year segment of the owner's business-day-adjusted registration date
54	     * (see {@link FiscalYearResolver#fiscalYearSuffix}); {@code HASH8} is the first 8 upper-case hex characters of the
55	     * SHA-256 digest of the normalized telephone (see {@link TelephoneNormalizer#canonicalize}) concatenated with the
56	     * owner's last name; and {@code CHK} is a single Luhn check digit (see {@link CheckDigitResolver#deriveCheckDigit})
57	     * computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW271A2B3C4D7}). Being a pure function of the
58	     * postcode, registration date, telephone and last name it carries no sequence number and is stable for a given owner.
59	     *
60	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized and its registration
61	     *              date resolved
62	     * @return the generated member id
63	     */
64	    public String deriveMemberId(Owner owner) {
65	        String base = regionCode(owner) + FiscalYearResolver.fiscalYearSuffix(owner.getRegistrationDate())
66	            + hash8(owner);
67	        return base + CheckDigitResolver.deriveCheckDigit(base);
68	    }
69	
70	    /**
71	     * Returns the {@code REGION} segment of the owner's identifier: the owner's plain region code (see
72	     * {@link LocalityResolver#regionCode}, derived from the owner's postcode, {@link LocalityResolver#UNKNOWN} when it
73	     * maps to no known region). Factored out of {@link #deriveMemberId} so the region segment has a single home, shared
74	     * by every identifier the owner's region prefixes, and expressed against the one shared plain region code so the
75	     * identifier's region and the owner's locality stay in step.
76	     *
77	     * @param owner the owner whose region segment should be derived
78	     * @return the region code, or {@link LocalityResolver#UNKNOWN} when the postcode maps to no known region
79	     */
80	    private String regionCode(Owner owner) {
81	        return LocalityResolver.regionCode(owner.getPostcode());
82	    }
83	
84	    /**
85	     * Returns the {@code HASH8} segment of the owner's identifier: the first 8 upper-case hex characters of the SHA-256
86	     * digest (see {@link HexDigest#upperHexPrefix}) of the owner's canonical telephone (see
87	     * {@link TelephoneNormalizer#canonicalize}) concatenated with the owner's last name. Factored out of
88	     * {@link #deriveMemberId} so the hash segment has a single home, shared by every identifier the owner's hash
89	     * contributes to.
90	     *
91	     * @param owner the owner whose hash segment should be derived, with its telephone already normalized
92	     * @return the 8-character upper-case hash segment
93	     */
94	    private String hash8(Owner owner) {
95	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
96	        return HexDigest.upperHexPrefix(telephone + owner.getLastName(), 8);
97	    }
98	}
