12	 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
13	 * See the License for the specific language governing permissions and
14	 * limitations under the License.
15	 */
16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	/**
20	 * Immutable structured audit event recording that an owner was created. Emitted to the dedicated {@code AUDIT} logger as
21	 * a JSON object alongside the human-readable audit line (see
22	 * {@link OwnerRestControllerV1#auditOwnerCreated(org.springframework.samples.petclinic.model.Owner)}).
23	 *
24	 * <p>The event carries the owner's primary identifier in its {@code primaryId} field: the unified {@code memberId}. The
25	 * field records "the owner's identity" rather than any one named column, and is rendered under the {@code memberId} JSON
26	 * key, matching the identifier it carries.
27	 *
28	 * @param seq         monotonically increasing sequence number across all owner creates
29	 * @param ownerId     the newly created owner's generated id
30	 * @param primaryId   the owner's primary identifier (the {@code memberId})
31	 * @param membershipLevel the owner's membership level at creation
32	 */
33	record OwnerCreatedEvent(long seq, Integer ownerId, String primaryId, int membershipLevel) {
34	
35	    /** The fixed {@code event} discriminator every owner-created event carries. */
36	    static final String EVENT_TYPE = "OWNER_CREATED";
37	
38	    /**
39	     * Renders this event as a compact JSON object
40	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}, with the primary identifier
41	     * under the {@code memberId} key. String values are JSON-escaped; a {@code null} identifier is rendered as JSON
42	     * {@code null}.
43	     *
44	     * @return the event serialized as a single-line JSON object
45	     */
46	    String toJson() {
47	        return "{"
48	            + "\"seq\":" + seq
49	            + ",\"ownerId\":" + ownerId
50	            + ",\"memberId\":" + jsonString(primaryId)
51	            + ",\"membershipLevel\":" + membershipLevel
52	            + ",\"event\":" + jsonString(EVENT_TYPE)
53	            + "}";
54	    }
55	
56	    private static String jsonString(String value) {
57	        if (value == null) {
58	            return "null";
59	        }
60	        StringBuilder sb = new StringBuilder(value.length() + 2);
61	        sb.append('"');
62	        for (int i = 0; i < value.length(); i++) {
63	            char c = value.charAt(i);
64	            switch (c) {
65	                case '"' -> sb.append("\\\"");
66	                case '\\' -> sb.append("\\\\");
67	                case '\n' -> sb.append("\\n");
68	                case '\r' -> sb.append("\\r");
69	                case '\t' -> sb.append("\\t");
70	                default -> {
71	                    if (c < 0x20) {
72	                        sb.append(String.format("\\u%04x", (int) c));
73	                    }
74	                    else {
75	                        sb.append(c);
76	                    }
77	                }
78	            }
79	        }
80	        sb.append('"');
81	        return sb.toString();
82	    }
83	}
