27	import java.util.concurrent.atomic.AtomicLong;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.HouseholdResolver;
35	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
36	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.Region;
40	import org.springframework.samples.petclinic.mapper.SoundexResolver;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
46	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
47	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
49	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
51	import org.springframework.samples.petclinic.rest.api.OwnersApi;
52	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
53	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.PetDto;
55	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.VisitDto;
57	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
58	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
59	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
60	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
61	import org.springframework.samples.petclinic.service.ClinicService;
62	import org.springframework.security.access.prepost.PreAuthorize;
63	import org.springframework.web.bind.annotation.CrossOrigin;
64	import org.springframework.web.bind.annotation.RequestMapping;
65	import org.springframework.web.bind.annotation.RestController;
66	import org.springframework.web.util.UriComponentsBuilder;
67	
68	import jakarta.servlet.http.HttpServletRequest;
69	import jakarta.transaction.Transactional;
70	
71	/**
72	 * @author Vitaliy Fedoriv
73	 */
74	
75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /** Dedicated notification logger; a successful create enqueues a welcome notification here carrying the new owner's id and member id. */
84	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
85	
86	    /**
87	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
88	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
89	     * controller instance handled the request.
90	     */
91	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
92	
93	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
94	    private static final int MAX_OWNERS_PER_CITY = 50;
95	
96	    /** Once a city already holds at least this many owners (but is not yet full), a further create there is flagged with a capacity warning. */
97	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
98	
99	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
100	    private static final int MAX_OWNERS_PER_DAY = 100;
101	
102	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
103	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
104	
105	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
106	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
107	
108	    /**
109	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
110	     * create with an already-seen key returns the original owner instead of creating a duplicate.
111	     */
112	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
113	
114	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
115	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
116	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
117	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
118	
119	    private final ClinicService clinicService;
120	
121	    private final OwnerMapper ownerMapper;
122	
123	    private final PetMapper petMapper;
124	
125	    private final VisitMapper visitMapper;
126	
127	    private final TelephoneNormalizer telephoneNormalizer;
128	
129	    private final AddressNormalizer addressNormalizer;
130	
131	    private final EmailNormalizer emailNormalizer;
132	
133	    private final IdentityKeyResolver identityKeyResolver;
134	
135	    private final HouseholdResolver householdResolver;
136	
137	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
138	    private final HttpServletRequest request;
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper,
144	                                 TelephoneNormalizer telephoneNormalizer,
145	                                 AddressNormalizer addressNormalizer,
146	                                 EmailNormalizer emailNormalizer,
147	                                 IdentityKeyResolver identityKeyResolver,
148	                                 HouseholdResolver householdResolver,
149	                                 HttpServletRequest request) {
150	        this.clinicService = clinicService;
151	        this.ownerMapper = ownerMapper;
152	        this.petMapper = petMapper;
153	        this.visitMapper = visitMapper;
154	        this.telephoneNormalizer = telephoneNormalizer;
155	        this.addressNormalizer = addressNormalizer;
156	        this.emailNormalizer = emailNormalizer;
157	        this.identityKeyResolver = identityKeyResolver;
158	        this.householdResolver = householdResolver;
159	        this.request = request;
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
165	        Collection<Owner> owners;
166	        if (lastName != null) {
167	            owners = this.clinicService.findOwnerByLastName(lastName);
168	        } else {
169	            owners = this.clinicService.findAllOwners();
170	        }
171	        if (owners.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        owners.forEach(this::populateHouseholdMemberCount);
175	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
176	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        populateHouseholdMemberCount(owner);
187	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
188	    }
189	
190	    /**
191	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
192	     * it depends on more than the single owner: the {@code identityKey} (see
193	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
194	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
195	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
196	     * mapper's uncapped one on the returned DTO.
197	     *
198	     * @param owner the owner to map
199	     * @return the owner DTO carrying its identity key and household-capped membership level
200	     */
201	    private OwnerDto toOwnerDto(Owner owner) {
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        stampIdentity(ownerDto, owner);
204	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
205	        return ownerDto;
206	    }
207	
208	    /**
209	     * Stamps onto a mapped owner DTO the identity values the mapper cannot produce on its own. The {@code identityKey}
210	     * (see {@link IdentityKeyResolver#deriveIdentityKey}) is not a stored field of the owner, so it is derived and set
211	     * here; the owner's {@code memberId} and {@code householdId} are already mapped straight off the owner. Kept as the
212	     * single home for assembling the owner's response identity so the shape of that identity is changed in one place.
213	     *
214	     * @param ownerDto the mapped owner DTO to stamp
215	     * @param owner    the owner the DTO was mapped from
216	     */
217	    private void stampIdentity(OwnerDto ownerDto, Owner owner) {
218	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Transactional
223	    @Override
224	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
225	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
226	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
227	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
228	            if (replay != null) {
229	                return replay;
230	            }
231	        }
232	        Owner owner = createOwner(ownerFieldsDto);
233	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
234	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
235	        }
236	        return createdOwnerResponse(owner);
237	    }
238	
239	    /**
240	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
241	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
242	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
243	     * normally.
244	     *
245	     * @param idempotencyKey the client-supplied idempotency key from the request header
246	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
247	     */
248	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
249	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
250	        if (existingId == null) {
251	            return null;
252	        }
253	        Owner owner = this.clinicService.findOwnerById(existingId);
254	        if (owner == null) {
255	            return null;
256	        }
257	        populateHouseholdMemberCount(owner);
258	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
259	    }
260	
261	    /**
262	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
263	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
264	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
265	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
266	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
267	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
268	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
269	     *
270	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
271	     * @return the newly created, persisted owner
272	     */
273	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
274	        normalizeAndValidate(ownerFieldsDto);
275	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
276	        populateDerivedFields(owner, ownerFieldsDto);
277	        requireUniqueIdentity(owner);
278	        flagPossibleDuplicate(owner, ownerFieldsDto);
279	        this.clinicService.saveOwner(owner);
280	        populateHouseholdMemberCount(owner);
281	        auditOwnerCreated(owner);
282	        enqueueWelcomeNotification(owner);
283	        return owner;
284	    }
285	
286	    /**
287	     * Enqueues a welcome notification for a newly created owner by emitting a single line to the dedicated
288	     * {@link #NOTIFY} logger, carrying the owner's id and its {@code memberId} so the notification can be addressed to
289	     * the new member.
290	     *
291	     * @param owner the newly created, persisted owner, with all its derived fields already in place
292	     */
293	    private void enqueueWelcomeNotification(Owner owner) {
294	        NOTIFY.info("welcome notification enqueued: id={} memberId={}", owner.getId(), owner.getMemberId());
295	    }
296	
297	    /**
298	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
299	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
300	     * canonical URL.
301	     *
302	     * @param owner the newly created, persisted owner
303	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
304	     */
305	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
306	        OwnerDto ownerDto = toOwnerDto(owner);
307	        HttpHeaders headers = new HttpHeaders();
308	        headers.setLocation(UriComponentsBuilder.newInstance()
309	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
310	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    /**
314	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
315	     * its id, member id and registration date alongside the membership level (see
316	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
317	     *
318	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
319	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
320	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see
321	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
322	     *
323	     * @param owner the newly created, persisted owner, with all its derived fields already in place
324	     */
325	    private void auditOwnerCreated(Owner owner) {
326	        logOwnerCreated(owner);
327	        publishOwnerCreatedEvent(owner);
328	    }
329	
330	    /**
331	     * Emits the human-readable audit line for a successfully created owner to the dedicated {@link #AUDIT} logger,
332	     * recording its id, member id and registration date alongside the membership level (see
333	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
334	     *
335	     * @param owner the newly created, persisted owner, with all its derived fields already in place
336	     */
337	    private void logOwnerCreated(Owner owner) {
338	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
339	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
340	            MembershipLevelResolver.deriveMembershipLevel(owner));
341	    }
342	
343	    /**
344	     * Emits the single immutable structured {@link OwnerCreatedEvent} for a successfully created owner as JSON to the
345	     * dedicated {@link #AUDIT} logger, carrying a monotonically increasing {@code seq} (see
346	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see {@link #primaryIdentifier(Owner)})
347	     * and its membership level under the {@code OWNER_CREATED} event type. Kept as the single home for building the
348	     * structured event so its schema is changed in one place.
349	     *
350	     * @param owner the newly created, persisted owner, with all its derived fields already in place
351	     */
352	    private void publishOwnerCreatedEvent(Owner owner) {
353	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
354	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
355	        AUDIT.info(event.toJson());
356	    }
357	
358	    /**
359	     * Returns the owner's primary identifier — the unified {@code memberId} the structured {@link OwnerCreatedEvent}
360	     * carries as the owner's identity.
361	     *
362	     * @param owner the newly created, persisted owner
363	     * @return the owner's member id
364	     */
365	    private String primaryIdentifier(Owner owner) {
366	        return owner.getMemberId();
367	    }
368	
369	    /**
370	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
371	     * already exist, in the order each field depends on. The {@code memberId} is derived from the owner's own
372	     * fields (see {@link IdentityKeyResolver#deriveMemberId}); the {@code namesakeCount} (see
373	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
374	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
375	     * this owner is saved, so none counts the new owner itself; and the shared
376	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
377	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
378	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
379	     *
380	     * @param owner          the newly mapped owner about to be saved
381	     * @param ownerFieldsDto the incoming owner payload
382	     */
383	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
384	        owner.setMemberId(deriveUniqueMemberId(owner));
385	        owner.setNamesakeCount(countNamesakes(owner));
386	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
387	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
388	        assignHouseholdId(owner);
