391	    /**
392	     * Derives an owner's {@code memberId} and de-duplicates it against the owners that already exist. The base id
393	     * is the pure derivation (see {@link IdentityKeyResolver#deriveMemberId}); when it collides with an existing
394	     * owner's {@code memberId} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
395	     * makes the whole id unique. Evaluated before the new owner is saved, so the collision check reflects only owners
396	     * that predate this create; distinct owners therefore always receive distinct member ids.
397	     *
398	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
399	     * @return the de-duplicated member id, unique across all existing owners
400	     */
401	    private String deriveUniqueMemberId(Owner owner) {
402	        String base = identityKeyResolver.deriveMemberId(owner);
403	        Collection<Owner> existing = this.clinicService.findAllOwners();
404	        String candidate = base;
405	        int n = 2;
406	        while (isMemberIdInUse(candidate, existing)) {
407	            candidate = base + "-" + n;
408	            n++;
409	        }
410	        return candidate;
411	    }
412	
413	    private boolean isMemberIdInUse(String memberId, Collection<Owner> existing) {
414	        return existing.stream().anyMatch(other -> memberId.equals(other.getMemberId()));
415	    }
