417	    /**
418	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
419	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
420	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
421	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
422	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
423	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
424	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
425	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
426	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
427	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
428	     * assigned (see {@link #requireUniqueIdentity}).
429	     *
430	     * @param ownerFieldsDto the incoming owner payload, mutated in place
431	     * @throws MissingOwnerFieldsException if any required field is missing or blank
432	     */
433	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
434	        normalizeAddress(ownerFieldsDto);
435	        validateRequiredFields(ownerFieldsDto);
436	        validatePostcode(ownerFieldsDto);
437	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
438	        ownerFieldsDto.setTelephone(telephone);
439	        requireCityHasCapacity(ownerFieldsDto.getCity());
440	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
441	        ownerFieldsDto.setRegistrationDate(registrationDate);
442	        requireDailyLimitNotReached(registrationDate);
443	        normalizeEmail(ownerFieldsDto);
444	    }
