446	    /**
447	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
448	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
449	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
450	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
451	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
452	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
453	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
454	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
455	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
456	     *
457	     * @param ownerFieldsDto the incoming owner payload, mutated in place
458	     */
459	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
460	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
461	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
462	        if (!line1.isEmpty()) {
463	            ownerFieldsDto.setAddressLine1(line1);
464	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
465	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
466	        }
467	        else {
468	            ownerFieldsDto.setAddressLine1(null);
469	            ownerFieldsDto.setAddressLine2(null);
470	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
471	        }
472	    }
