474	    /**
475	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
476	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
477	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
478	     * place so the caller can map and save it directly.
479	     *
480	     * @param ownerFieldsDto the incoming owner payload, mutated in place
481	     */
482	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
483	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
484	    }
