486	    /**
487	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
488	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
489	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
490	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
491	     * date is rejected.
492	     *
493	     * @param ownerFieldsDto the incoming owner payload
494	     * @return the effective registration date rolled forward onto a business day
495	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
496	     */
497	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
498	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
499	        if (effective == null) {
500	            effective = LocalDate.now();
501	        }
502	        else if (effective.isAfter(LocalDate.now())) {
503	            throw new FutureRegistrationDateException(
504	                "the registration date must not be later than the current server date");
505	        }
506	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
507	            || PUBLIC_HOLIDAYS.contains(effective)) {
508	            effective = effective.plusDays(1);
509	        }
510	        return effective;
511	    }
