513	    /**
514	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
515	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
516	     * further owner may be created for that day.
517	     *
518	     * @param registrationDate the adjusted business-day registration date of the owner being created
519	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
520	     */
521	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
522	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
523	            throw new DailyOwnerLimitExceededException(
524	                "the maximum number of owners for today has already been reached");
525	        }
526	    }
