582	     * @param ownerFieldsDto the owner payload to validate
583	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
584	     */
585	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
586	        List<String> missingFields = new ArrayList<>();
587	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
