604	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
605	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
606	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
607	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
608	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
609	     *
610	     * @param ownerFieldsDto the incoming owner payload
611	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
612	     */
613	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
614	        String postcode = ownerFieldsDto.getPostcode();
615	        if (postcode == null) {
616	            return;
617	        }
618	        Region region = Region.forCity(ownerFieldsDto.getCity());
619	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
620	            throw new InvalidPostcodeException(
621	                "postcode " + postcode + " is not valid for the city's region " + region.name());
622	        }
