625	    /**
626	     * Rejects creating an owner whose whole derived {@code identityKey} (see
627	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
628	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
629	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
630	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
631	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
632	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
633	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
634	     * does not block the create.
635	     *
636	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
637	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
638	     */
639	    private void requireUniqueIdentity(Owner owner) {
640	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
641	        boolean inUse = this.clinicService.findAllOwners().stream()
642	            .filter(existing -> !existing.isDeleted())
643	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
644	        if (inUse) {
645	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
646	        }
647	    }
