649	    /**
650	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
651	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
652	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
653	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
654	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
655	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
656	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
657	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
658	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
659	     *
660	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
661	     * @param ownerFieldsDto the incoming owner payload
662	     */
663	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
664	        owner.setPossibleDuplicate(false);
665	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
666	            return;
667	        }
668	        String postcode = owner.getPostcode();
669	        if (postcode == null || postcode.isBlank()) {
670	            return;
671	        }
672	        for (Owner existing : this.clinicService.findAllOwners()) {
673	            if (isPossibleDuplicateOf(owner, existing)) {
674	                owner.setPossibleDuplicate(true);
675	                owner.setPossibleDuplicateOf(existing.getId());
676	                return;
677	            }
678	        }
679	    }
