681	    /**
682	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
683	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
684	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
685	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
686	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
687	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
688	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
689	     *
690	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
691	     * @param existing an already-persisted owner to test the new owner against
692	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
693	     */
694	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
695	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
696	            && owner.getPostcode().equals(existing.getPostcode())
697	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
698	    }
