761	    /**
762	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
763	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
764	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
765	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
766	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
767	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
768	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
769	     *
770	     * @param owner the owner whose capped membership level should be computed
771	     * @return the membership level, capped at one above the existing household maximum
772	     */
773	    private int cappedMembershipLevel(Owner owner) {
774	        populateHouseholdMemberCount(owner);
775	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
776	        Integer cap = householdMembershipLevelCap(owner);
777	        return cap == null ? level : Math.min(level, cap);
778	    }
779	
780	    /**
781	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
782	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
783	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
784	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
785	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
786	     * member has no cap.
787	     *
788	     * @param owner the owner whose household level cap should be computed
789	     * @return one above the existing household maximum level, or {@code null} when no cap applies
790	     */
791	    private Integer householdMembershipLevelCap(Owner owner) {
792	        String householdId = owner.getHouseholdId();
793	        Integer id = owner.getId();
794	        if (householdId == null || id == null) {
795	            return null;
796	        }
797	        Integer maxLevel = null;
798	        for (Owner member : this.clinicService.findAllOwners()) {
799	            Integer memberId = member.getId();
800	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
801	                int memberLevel = cappedMembershipLevel(member);
802	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
803	            }
804	        }
805	        return maxLevel == null ? null : maxLevel + 1;
806	    }
