808	    /**
809	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
810	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
811	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
812	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
813	     * already been saved it is itself among the members returned.
814	     *
815	     * @param owner the owner whose household members should be resolved
816	     * @return the members of the owner's household, never empty
817	     */
818	    private List<Owner> householdMembers(Owner owner) {
819	        String householdId = owner.getHouseholdId();
820	        if (householdId == null) {
821	            return List.of(owner);
822	        }
823	        return this.clinicService.findAllOwners().stream()
824	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
825	            .toList();
826	    }
