851	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
852	        currentOwner.setLastName(ownerFieldsDto.getLastName());
853	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
854	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
855	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
856	        this.clinicService.saveOwner(currentOwner);
857	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
858	    }
859	
860	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
861	    @Transactional
862	    @Override
863	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
864	        Owner owner = this.clinicService.findOwnerById(ownerId);
865	        if (owner == null) {
866	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
867	        }
868	        owner.setDeleted(true);
869	        this.clinicService.saveOwner(owner);
870	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
871	    }
872	
873	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
874	    @Override
875	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
876	        Owner owner = this.clinicService.findOwnerById(ownerId);
877	        if (owner == null) {
878	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
879	        }
880	        HttpHeaders headers = new HttpHeaders();
881	        Pet pet = petMapper.toPet(petFieldsDto);
882	        owner.setId(ownerId);
883	        pet.setOwner(owner);
884	        pet.getType().setName(null);
885	        this.clinicService.savePet(pet);
886	        PetDto petDto = petMapper.toPetDto(pet);
887	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
888	            .buildAndExpand(pet.getId()).toUri());
889	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
890	    }
891	
892	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
893	    @Override
894	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
895	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
896	        if (currentOwner != null) {
897	            Pet currentPet = this.clinicService.findPetById(petId);
898	            if (currentPet != null) {
899	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
900	                currentPet.setName(petFieldsDto.getName());
901	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
902	                this.clinicService.savePet(currentPet);
903	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
904	            }
905	        }
906	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
907	    }
908	
909	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
910	    @Override
911	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
912	        HttpHeaders headers = new HttpHeaders();
913	        Visit visit = visitMapper.toVisit(visitFieldsDto);
914	        Pet pet = new Pet();
915	        pet.setId(petId);
916	        visit.setPet(pet);
917	        this.clinicService.saveVisit(visit);
918	        VisitDto visitDto = visitMapper.toVisitDto(visit);
919	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
920	            .buildAndExpand(visit.getId()).toUri());
921	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
922	    }
923	
924	
925	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
926	    @Override
927	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
928	        Owner owner = this.clinicService.findOwnerById(ownerId);
929	        if (owner != null) {
930	            Pet pet = owner.getPet(petId);
931	            if (pet != null) {
932	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
